What integer is printed by the following C program?
```c
#include <stdio.h>
int fun(int n) {
    static int c = 0;
    c += n;
    return c;
}
int main() {
    int s = 0;
    for (int i = 1; i <= 4; i++) s = fun(i);
    printf("%d", s);
    return 0;
}
```

What integer is printed by the following C program?
```c
#include <stdio.h>
int f(int x, int y) {
    if (y == 0) return x;
    return f(x + y, y - 1);
}
int main() {
    printf("%d", f(3, 5));
    return 0;
}
```
